   "\u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 \u092c\u0928\u093e\u0935\u091f: \u0915\u094b\u0908 \u0935\u093f\u091c\u094d\u091e\u093e\u092a\u0928 \u0928\u0939\u0940\u0902, \u0917\u093c\u0932\u0924\u0940 \u0938\u0947 \u0926\u092c\u093e\u0928\u0947 \u0932\u093e\u092f\u0915 \u0915\u0941\u091b \u0928\u0939\u0940\u0902, \u091b\u094b\u091f\u0947 \u0915\u093e\u0928\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f \u0906\u0935\u093e\u091c\u093c \u0915\u0940 \u0938\u0940\u092e\u093e, \u0914\u0930 \u092c\u091c\u093e\u0924\u0947 \u0938\u092e\u092f \u092e\u0947\u0928\u0942 \u0905\u092a\u0928\u0947-\u0906\u092a \u091b\u093f\u092a \u091c\u093e\u0924\u0947 \u0939\u0948\u0902\u0964",
