   "\u091a\u0941\u0928\u094c\u0924\u0940 \u090f\u0915 \u0915\u094d\u0932\u0947\u092b\u093c \u0915\u0947 \u0938\u092d\u0940 8 \u0938\u0941\u0930 \u0915\u094d\u0930\u092e\u0930\u0939\u093f\u0924 \u092a\u0942\u091b\u0924\u0940 \u0939\u0948 \u2014 \u0938\u0941\u0930 \u092a\u0922\u093c\u0928\u0947 \u0915\u0940 \u0924\u0947\u091c\u093c \u0914\u0930 \u092e\u091c\u093c\u0947\u0926\u093e\u0930 \u091c\u093e\u0901\u091a\u0964",
