    "\u0915\u094d\u092f\u093e \u092f\u0939 \u092e\u0947\u0930\u0947 \u092c\u091a\u094d\u091a\u0947 \u0915\u0940 \u091c\u093e\u0928\u0915\u093e\u0930\u0940 \u0907\u0915\u091f\u094d\u0920\u093e \u0915\u0930\u0924\u093e \u0939\u0948?",
    "\u0915\u094b\u0908 \u0928\u093f\u091c\u0940 \u091c\u093e\u0928\u0915\u093e\u0930\u0940 \u0928\u0939\u0940\u0902 \u0932\u0940 \u091c\u093e\u0924\u0940\u0964 \u092d\u093e\u0937\u093e \u091c\u0948\u0938\u0940 \u0938\u0947\u091f\u093f\u0902\u0917 \u0938\u093f\u0930\u094d\u092b\u093c \u0906\u092a\u0915\u0947 \u0921\u093f\u0935\u093e\u0907\u0938 \u092a\u0930 \u0938\u0939\u0947\u091c\u0940 \u091c\u093e\u0924\u0940 \u0939\u0948\u0902\u0964 \u0905\u0938\u0932\u0940 \u092a\u093f\u092f\u093e\u0928\u094b \u092e\u094b\u0921 \u092e\u0947\u0902 \u092e\u093e\u0907\u0915\u094d\u0930\u094b\u092b\u093c\u094b\u0928 \u0915\u0940 \u0906\u0935\u093e\u091c\u093c \u0938\u0941\u0930 \u092a\u0939\u091a\u093e\u0928\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0921\u093f\u0935\u093e\u0907\u0938 \u092a\u0930 \u0939\u0940 \u091c\u093e\u0901\u091a\u0940 \u091c\u093e\u0924\u0940 \u0939\u0948 \u0914\u0930 \u0915\u0939\u0940\u0902 \u092d\u0947\u091c\u0940 \u0928\u0939\u0940\u0902 \u091c\u093e\u0924\u0940\u0964"
